INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Masalah: Bahasa Thailand Terdengar Sulit Bagi Pemula$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Bagi banyak orang Indonesia, bahasa Thailand terdengar seperti rangkaian bunyi yang sulit diuraikan. Hurufnya berbeda, nadanya naik-turun, dan banyak bunyi yang tidak ada dalam bahasa Indonesia. Akibatnya, banyak wisatawan Indonesia yang bepergian ke Thailand memilih hanya memakai bahasa isyarat atau bahasa Inggris yang terbatas. Padahal, menguasai beberapa sapaan dasar sudah cukup untuk membuat interaksi pertama berjalan hangat dan sopan.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Penjelasan: Lima Nada dan Budaya Kesopanan$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Bahasa Thailand adalah bahasa bernada dengan lima nada: datar, rendah, menurun, tinggi, dan naik. Arti kata bisa berubah total hanya karena perbedaan nada — misalnya kata "khao" bisa berarti nasi, gunung, atau masuk, tergantung nadanya. Selain itu, budaya Thailand sangat menghargai kesopanan: sapaan dan ungkapan sopan disertai kata penutup "khrap" untuk laki-laki dan "kha" untuk perempuan.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Persiapan$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $body$Siapkan daftar sapaan dasar beserta panduan pelafalannya, aplikasi kamus atau penerjemah untuk latihan, dan kesempatan berlatih pengucapan. Fokuslah pada sapaan dan ungkapan paling sering dipakai, bukan menghafal banyak kata sekaligus.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Langkah 1: Ucapkan Sapaan Dasar$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Sawaddii khrap/kha — halo / selamat (dipakai pagi, siang, malam)$txt$, $txt$Khop khun khrap/kha — terima kasih$txt$, $txt$Khor thot khrap/kha — maaf / permisi$txt$, $txt$Chai / Mai chai — ya / tidak$txt$, $txt$Tao rai? — berapa harganya?$txt$, $txt$Ao / Mai ao — mau / tidak mau$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Langkah 2: Ikuti Gerakan Wai dan Latih Nada$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Saat mengucapkan "sawaddii", lakukan gerakan wai: rapatkan kedua telapak tangan di depan dada seperti berdoa, lalu anggukkan kepala sedikit. Jangan khawatir soal nada yang sempurna di awal — penutur asli umumnya memahami maksud wisatawan dari konteks. Latih satu kata sampai bunyinya stabil, baru lanjut ke kata berikutnya, dan kalau memungkinkan dengarkan contoh pengucapan dari penutur asli.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Risiko, Pemeriksaan, dan Tindak Lanjut$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $body$Risiko utama adalah salah nada sehingga kata terdengar berbeda artinya; ini wajar untuk pemula dan jarang menimbulkan masalah serius. Hindari mencoba kata-kata yang belum dipahami artinya. Uji kemampuan Anda dengan menyapa penjaga hotel atau penjual pasar dengan "sawaddii khrap/kha" disertai wai — jika mereka tersenyum dan membalas, sapaan Anda berhasil. Setelah itu, perluas kosakata perlahan: "Yuu thii nai?" (di mana?), angka 1 sampai 10 untuk tawar-menawar, dan "Poot thai mai dai" (saya tidak bisa berbahasa Thailand) untuk situasi sulit.$body$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Masalah: Telinga Berdenging Terus-Menerus$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Telinga berdenging — yang dalam istilah medis disebut tinnitus — adalah sensasi mendengar bunyi berdenging, berdengung, atau berdesis padahal tidak ada sumber suara di sekitar. Banyak orang mengalaminya sesekali setelah mendengar suara keras, tetapi sebagian mengalaminya terus-menerus sehingga mengganggu tidur, konsentrasi, dan kualitas hidup.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Penjelasan: Apa yang Terjadi di Telinga$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Tinnitus terjadi ketika sistem pendengaran mengirim sinyal ke otak tanpa ada rangsangan suara nyata. Penyebab umum meliputi penumpukan kotoran telinga (serumen), paparan suara keras, infeksi telinga, penuaan, tekanan darah tinggi, efek samping obat tertentu, dan gangguan pada tulang-tulang pendengaran. Sebagian besar kasus bersifat ringan dan sementara. Catatan: artikel ini bersifat informasi umum dan bukan pengganti diagnosis dokter.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Langkah 1: Periksa Kotoran Telinga$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $body$Penumpukan kotoran telinga adalah penyebab paling umum dan paling mudah diatasi. Jangan mengorek telinga dengan cotton bud atau benda tajam karena bisa mendorong kotoran lebih dalam dan melukai gendang telinga. Jika dicurigai ada penumpukan, minta dokter membersihkannya dengan cara yang aman.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Langkah 2: Kurangi Paparan Suara Keras$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Paparan suara keras — konser, mesin, atau earphone dengan volume tinggi — adalah penyebab utama tinnitus jangka panjang. Gunakan pelindung telinga di lingkungan bising, batasi volume earphone, dan beri telinga waktu istirahat dari kebisingan.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Langkah 3: Kelola Pemicu Lain$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Kurangi konsumsi kafein, alkohol, dan rokok yang dapat memperburuk denging.$txt$, $txt$Kelola stres dengan tidur cukup dan relaksasi — stres memperparah persepsi denging.$txt$, $txt$Periksa tekanan darah secara rutin bila ada riwayat hipertensi.$txt$, $txt$Catat obat yang sedang dikonsumsi dan diskusikan dengan dokter bila denging muncul setelah minum obat baru.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Risiko, Pemeriksaan, dan Tindak Lanjut$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $body$Risiko terbesar adalah mengabaikan tinnitus yang sebenarnya gejala kondisi serius. Segera ke dokter THT bila: denging hanya pada satu telinga, penurunan pendengaran mendadak, pusing berputar hebat, keluar cairan atau darah dari telinga, atau denging berdenyut mengikuti detak jantung. Pantau selama satu minggu — catat kapan denging muncul dan apa pemicunya — lalu bawa catatan itu saat konsultasi. Untuk tinnitus kronis, dokter dapat menyarankan terapi suara, alat bantu dengar, atau terapi perilaku kognitif.$body$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Apa Itu Gurun?$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Gurun adalah wilayah yang menerima curah hujan sangat sedikit — umumnya kurang dari 250 milimeter per tahun — sehingga vegetasi sulit tumbuh. Banyak orang membayangkan gurun selalu panas dan berpasir, padahal ada juga gurun dingin dan gurun kutub yang tertutup es. Definisi gurun didasarkan pada kekeringan, bukan suhu.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Gurun Terluas di Dunia$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Gurun terluas di dunia adalah Gurun Kutub Antarktika dengan luas sekitar 14 juta kilometer persegi — hampir seluas seluruh benua Antarktika. Meskipun tertutup es, wilayah ini memenuhi definisi gurun karena curah hujannya sangat rendah. Gurun panas terluas adalah Sahara di Afrika Utara dengan luas sekitar 9 juta kilometer persegi — hampir seluas Amerika Serikat — membentang di 11 negara dengan suhu siang yang bisa melampaui 50 derajat Celsius.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Gurun-Gurun Besar Lainnya$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Gurun Kutub Arktik — sekitar 13,9 juta km², gurun dingin terbesar kedua.$txt$, $txt$Gurun Gobi (Mongolia-Tiongkok) — sekitar 1,3 juta km², terkenal dengan fosil dinosaurus.$txt$, $txt$Gurun Kalahari (Afrika Selatan) — sekitar 900 ribu km², semi-gurun dengan satwa liar.$txt$, $txt$Gurun Patagonia (Argentina) — sekitar 670 ribu km², gurun dingin terbesar di Amerika.$txt$, $txt$Gurun Great Victoria (Australia) — sekitar 650 ribu km².$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Bagaimana Gurun Terbentuk?$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Gurun terbentuk karena beberapa sebab: letak di zona tekanan udara tinggi subtropis yang menghambat pembentukan awan (seperti Sahara), efek bayangan hujan di balik pegunungan tinggi (seperti Gobi dan Patagonia), arus laut dingin yang mendinginkan udara (seperti Atacama), serta jarak yang sangat jauh dari sumber kelembapan (gurun kutub). Aktivitas manusia seperti penggundulan hutan dan pertanian berlebihan juga dapat memperluas gurun.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Kehidupan, Iklim, dan Fakta Menarik$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Meski tampak tandus, gurun menyimpan kehidupan yang luar biasa adaptif: unta menyimpan cadangan lemak di punuknya, kaktus menyimpan air di batangnya, dan suku Tuareg serta Badui telah hidup di gurun selama ribuan tahun. Para ilmuwan memantau gurun sebagai indikator perubahan iklim — Sahara tercatat meluas sekitar 10 persen dalam satu abad terakhir. Fakta menarik: Atacama di Chili adalah tempat terkering di Bumi, Sahara dulunya hijau dan berdanau ribuan tahun lalu, dan badai pasir Sahara bisa menerbangkan debu hingga menyuburkan hutan Amazon.$body$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Apa Itu 5G?$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$5G adalah generasi kelima teknologi jaringan seluler, penerus 4G LTE. Dibandingkan pendahulunya, 5G menawarkan kecepatan unduh yang jauh lebih tinggi, latensi (jeda respons) yang sangat rendah, dan kapasitas untuk menghubungkan jauh lebih banyak perangkat dalam satu area. 5G dirancang bukan hanya untuk ponsel, tetapi juga untuk mobil otonom, pabrik pintar, dan miliaran perangkat Internet of Things.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Kecepatan dan Latensi$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Secara teori, 5G dapat mencapai kecepatan hingga 10–20 Gbps — puluhan kali lebih cepat dari 4G. Namun keunggulan paling revolusioner adalah latensinya yang bisa serendah 1 milidetik, dibanding 30–50 milidetik pada 4G. Latensi super rendah ini memungkinkan aplikasi yang membutuhkan respons seketika, seperti operasi bedah jarak jauh dan kendali mesin industri.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Tiga Layanan Utama 5G$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$eMBB (Enhanced Mobile Broadband) — internet super cepat untuk ponsel, streaming 4K/8K, dan VR.$txt$, $txt$URLLC (Ultra-Reliable Low Latency) — komunikasi sangat andal dan cepat untuk mobil otonom dan industri.$txt$, $txt$mMTC (Massive Machine Type Communications) — menghubungkan hingga satu juta perangkat per kilometer persegi untuk IoT.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Dampak pada Kehidupan dan Industri$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Bagi pengguna biasa, 5G berarti mengunduh film dalam hitungan detik, video call tanpa macet, dan game online yang mulus; di kota besar, 5G mendukung kota pintar dengan lampu jalan adaptif dan manajemen lalu lintas real-time. Di industri, 5G memungkinkan pabrik pintar dengan robot terkoordinasi nirkabel, pemantauan mesin real-time, dan telemedicine canggih.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Tantangan, Isu Kesehatan, dan Masa Depan$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Penerapan 5G menghadapi tantangan: infrastruktur menara yang padat dan mahal, pengaturan spektrum frekuensi, serta keamanan siber. Soal kesehatan, WHO menyatakan sejauh ini tidak ada bukti ilmiah yang meyakinkan bahwa paparan radiasi 5G dalam batas yang ditetapkan berbahaya — radiasi 5G termasuk radiasi non-pengion yang tidak merusak DNA. Sementara 5G masih disebar global, peneliti sudah mengembangkan 6G yang ditargetkan hadir sekitar tahun 2030.$body$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Tujuan Pembelajaran$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menyebutkan kerajaan-kerajaan Hindu-Buddha di Indonesia beserta letak dan masa kejayaannya; (2) menjelaskan kehidupan ekonomi, sosial, dan budaya pada masa kerajaan Hindu-Buddha; (3) mengidentifikasi peninggalan sejarah kerajaan Hindu-Buddha; (4) menjelaskan pengaruh budaya Hindu-Buddha terhadap kehidupan masyarakat Indonesia.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Masuknya Pengaruh Hindu-Buddha$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Pengaruh Hindu-Buddha masuk ke Indonesia sekitar abad ke-2 hingga ke-4 Masehi melalui jalur perdagangan. Para pedagang dari India singgah di pelabuhan-pelabuhan Nusantara, dan bersama mereka datang pula para brahmana yang menyebarkan ajaran agama serta budaya. Proses ini berlangsung damai melalui akulturasi — perpaduan budaya pendatang dengan budaya lokal yang sudah ada.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Kerajaan Kutai dan Tarumanegara$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $body$Kerajaan Kutai di Kalimantan Timur (abad ke-4) adalah kerajaan Hindu tertua di Indonesia, dibuktikan oleh tujuh prasasti Yupa peninggalan Raja Mulawarman. Kerajaan Tarumanegara di Jawa Barat (abad ke-5) dipimpin Raja Purnawarman yang terkenal dengan prasasti Ciaruteun — jejak telapak kaki gajah yang disamakan dengan jejak kaki raja.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Sriwijaya dan Majapahit$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Sriwijaya (abad ke-7 hingga ke-13) berpusat di Sumatra dan menjadi kerajaan maritim Buddha terbesar di Asia Tenggara — menguasai jalur perdagangan Selat Malaka dan menjadi pusat pembelajaran agama Buddha. Majapahit (1293–1500 M) adalah kerajaan Hindu terbesar di Nusantara; pada masa Raja Hayam Wuruk dan Mahapatih Gajah Mada mencapai puncak kejayaan yang diabadikan dalam Sumpah Palapa dan kitab Negarakertagama karya Mpu Prapanca.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Kehidupan Masyarakat dan Peninggalan$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $body$Kehidupan masa Hindu-Buddha: ekonomi bertumpu pada pertanian dan perdagangan maritim; sosial mengenal sistem kasta yang berakulturasi dengan struktur lokal; budaya berkembang lewat seni sastra, arsitektur candi, dan upacara keagamaan; raja dianggap titisan dewa. Peninggalannya tersebar luas: Candi Borobudur (candi Buddha terbesar di dunia), Candi Prambanan, prasasti Yupa, Ciaruteun, dan Kedukan Bukit, serta karya sastra Negarakertagama dan Sutasoma yang memuat semboyan "Bhinneka Tunggal Ika".$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Latihan dan Kunci Jawaban$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $body$Contoh soal: (1) Sebutkan dua bukti tertua kerajaan Hindu di Indonesia! (2) Mengapa Sriwijaya disebut kerajaan maritim? (3) Jelaskan isi Sumpah Palapa! Latihan mandiri: buat peta silsilah raja Majapahit; jelaskan tiga bentuk akulturasi budaya Hindu-Buddha dengan budaya lokal; jelaskan dengan bahasamu mengapa Borobudur dianggap mahakarya dunia. Kunci: (1) Prasasti Yupa (Kutai) dan Ciaruteun (Tarumanegara); (2) kekuasaannya bertumpu pada penguasaan jalur perdagangan laut Selat Malaka; (3) tekad Gajah Mada menyatukan Nusantara sebelum menikmati kesenangan duniawi.$body$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_principal_id, access_level, status, attribution_type, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $body$Tujuan Pembelajaran$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $body$Setelah mempelajari materi ini, siswa diharapkan mampu: (1) menjelaskan pengertian paragraf dengan bahasa sendiri; (2) menyebutkan ciri-ciri paragraf yang baik; (3) menemukan kalimat utama dalam sebuah paragraf; (4) menyusun paragraf sederhana yang terdiri dari 3–5 kalimat.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $body$Apa Itu Paragraf?$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $body$Paragraf adalah karangan singkat yang terdiri dari beberapa kalimat dan membahas satu pokok pikiran. Bayangkan paragraf seperti satu gerbong kereta: semua kalimat di dalamnya berjalan ke arah yang sama, yaitu membahas satu topik. Dalam buku, paragraf mudah dikenali karena penulisannya menjorok ke dalam pada baris pertama.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $body$Ciri-Ciri Paragraf yang Baik$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Memiliki satu pokok pikiran (ide utama) yang jelas.$txt$, $txt$Terdiri dari beberapa kalimat yang saling berhubungan.$txt$, $txt$Kalimat pertama biasanya menjorok ke dalam (inden).$txt$, $txt$Semua kalimat mendukung pokok pikiran yang sama.$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $body$Kalimat Utama dan Contoh$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $body$Setiap paragraf memiliki kalimat utama — kalimat yang memuat pokok pikiran — sedangkan kalimat lainnya disebut kalimat penjelas yang mendukungnya. Contoh: "Kelinci adalah hewan yang lucu. Ia memiliki telinga panjang dan ekor yang pendek. Kelinci suka makan wortel dan sayuran hijau. Bulunya yang lembut membuatnya disukai anak-anak." Kalimat utamanya adalah kalimat pertama; tiga kalimat berikutnya menjelaskan mengapa kelinci itu lucu.$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $body$Cara Menyusun Paragraf Sederhana$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$txt$Tentukan dulu topik yang akan ditulis, misalnya "Kucingku".$txt$, $txt$Buat kalimat utama, misalnya "Kucingku bernama Moli."$txt$, $txt$Tambahkan 2–4 kalimat penjelas tentang Moli: warnanya, kesukaannya, kebiasaannya.$txt$, $txt$Baca ulang: pastikan semua kalimat membahas Moli, bukan topik lain.$txt$, $txt$Jangan lupa: baris pertama menjorok ke dalam!$txt$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $body$Latihan dan Kunci Jawaban$body$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $body$Contoh soal: (1) Apa yang dimaksud dengan paragraf? (2) Sebutkan dua ciri paragraf yang baik! (3) Tuliskan kalimat utama paragraf tentang kelinci di atas! Latihan mandiri: buat satu paragraf tentang hewan kesukaanmu (3–5 kalimat); tulis satu paragraf tentang kegiatanmu kemarin sore; tukar dengan teman sebangku dan temukan kalimat utamanya! Kunci: (1) karangan singkat dari beberapa kalimat yang membahas satu pokok pikiran; (2) satu pokok pikiran yang jelas dan kalimat-kalimat yang saling berhubungan; (3) "Kelinci adalah hewan yang lucu."$body$));
